  static void GpuLightingPlace(Canvas surface,UIElement child,double x,double y){Canvas.SetLeft(child,x);Canvas.SetTop(child,y);surface.Children.Add(child);}
  Grid GpuLightingViewport(Canvas surface){var grid=new Grid{Tag="GpuLighting.Viewport"};grid.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});grid.ColumnDefinitions.Add(new ColumnDefinition());grid.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});var viewer=new ScrollViewer{Content=surface,HorizontalScrollBarVisibility=ScrollBarVisibility.Hidden,VerticalScrollBarVisibility=ScrollBarVisibility.Disabled,HorizontalContentAlignment=HorizontalAlignment.Left,Tag="GpuLighting.Scroll"};Grid.SetColumn(viewer,1);grid.Children.Add(viewer);var left=Button("‹",()=>viewer.ScrollToHorizontalOffset(Math.Max(0,viewer.HorizontalOffset-264)));var right=Button("›",()=>viewer.ScrollToHorizontalOffset(viewer.HorizontalOffset+264));foreach(var arrow in new[]{left,right}){arrow.Width=18;arrow.Height=35;arrow.Padding=new Thickness(0);arrow.Margin=new Thickness(0);arrow.FontSize=20;arrow.VerticalAlignment=VerticalAlignment.Top;arrow.Background=Brushes.Transparent;arrow.BorderThickness=new Thickness(0);arrow.Visibility=Visibility.Collapsed;}Grid.SetColumn(right,2);grid.Children.Add(left);grid.Children.Add(right);viewer.ScrollChanged+=(sender,args)=>{left.Visibility=viewer.HorizontalOffset>0?Visibility.Visible:Visibility.Collapsed;right.Visibility=viewer.HorizontalOffset<viewer.ScrollableWidth?Visibility.Visible:Visibility.Collapsed;};return grid;}
  Canvas GpuLightingDeviceIcon(double width,double height){var icon=new Canvas{Width=width,Height=height,IsHitTestVisible=false};icon.Children.Add(new Rectangle{Width=width-7,Height=height*0.68,RadiusX=2,RadiusY=2,Stroke=muted,StrokeThickness=1.5,Margin=new Thickness(1,height*0.1,0,0)});for(int fan=0;fan<2;fan++){double size=height*0.43;icon.Children.Add(new Ellipse{Width=size,Height=size,Stroke=muted,StrokeThickness=1.5,Margin=new Thickness(width*(0.19+fan*0.42),height*0.23,0,0)});}icon.Children.Add(new Line{X1=width-3,Y1=0,X2=width-3,Y2=height*0.95,Stroke=muted,StrokeThickness=2});icon.Children.Add(new Line{X1=width*0.25,Y1=height*0.88,X2=width*0.7,Y2=height*0.88,Stroke=muted,StrokeThickness=2});return icon;}
  Canvas GpuLightingEffectIcon(int effect){
   if(effect<4)return KeyboardLightingEffectIcon(effect==3?4:effect,muted);if(effect==6)return KeyboardLightingEffectIcon(6,muted);if(effect==8)return HeadsetLightingBlinkIcon(muted);
   var icon=new Canvas{Width=64,Height=64,IsHitTestVisible=false};
   if(effect==4||effect==5){icon.Children.Add(new Ellipse{Width=30,Height=30,Stroke=muted,StrokeThickness=4,Margin=new Thickness(9,27,0,0)});icon.Children.Add(new Ellipse{Width=9,Height=9,Fill=muted,Margin=new Thickness(19.5,37.5,0,0)});if(effect==4){for(int streak=0;streak<2;streak++)icon.Children.Add(new Line{X1=28+streak*11,Y1=32,X2=44+streak*11,Y2=7,Stroke=muted,StrokeThickness=4});}else{icon.Children.Add(new Polyline{Points=new PointCollection(new[]{new Point(23,29),new Point(30,14),new Point(49,14)}),Stroke=muted,StrokeThickness=4});icon.Children.Add(new Ellipse{Width=10,Height=10,Stroke=muted,StrokeThickness=3,Margin=new Thickness(45,7,0,0)});}}
   else if(effect==7){icon.Children.Add(new Polyline{Points=new PointCollection(new[]{new Point(34,6),new Point(23,31),new Point(43,31),new Point(31,58)}),Stroke=muted,StrokeThickness=5});for(int n=0;n<3;n++)icon.Children.Add(new Line{X1=9+n*8,Y1=26,X2=17+n*8,Y2=7,Stroke=muted,StrokeThickness=4});}
   else {icon.Children.Add(new Polygon{Points=new PointCollection(new[]{new Point(32,9),new Point(56,32),new Point(32,55),new Point(8,32)}),Stroke=muted,StrokeThickness=4,Fill=Brushes.Transparent});for(int n=0;n<4;n++)icon.Children.Add(new Ellipse{Width=6,Height=6,Fill=muted,Margin=new Thickness(n%2==0?5:53,n<2?5:53,0,0)});}
   return icon;
